// В TypeScript нет встроенной кучи — пишем свою.
// Двоичная куча хранится в массиве: дети узла i — 2i + 1 и 2i + 2, родитель — (i - 1) >> 1.
class Heap<T> {
  private data: T[] = [];

  // less(a, b) === true, если a должен стоять ближе к вершине, чем b.
  // (a, b) => a < b — min-куча, (a, b) => a > b — max-куча
  constructor(private less: (a: T, b: T) => boolean) {}

  size(): number {
    return this.data.length;
  }

  // Вершина кучи (минимум или максимум) за O(1)
  peek(): T | undefined {
    return this.data[0];
  }

  // Добавление за O(log n): кладём в конец и «поднимаем» вверх
  push(value: T): void {
    const a = this.data;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      // Родитель уже «лучше» — порядок кучи восстановлен
      if (!this.less(a[i], a[parent])) break;
      [a[i], a[parent]] = [a[parent], a[i]];
      i = parent;
    }
  }

  // Извлечение вершины за O(log n): на её место ставим последний элемент и «топим» его вниз
  pop(): T | undefined {
    const a = this.data;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0 && last !== undefined) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        // Выбираем «лучшего» из узла и двух его детей
        let best = i;
        if (l < a.length && this.less(a[l], a[best])) best = l;
        if (r < a.length && this.less(a[r], a[best])) best = r;
        if (best === i) break;
        [a[i], a[best]] = [a[best], a[i]];
        i = best;
      }
    }
    return top;
  }
}

class MedianFinder {
  // Меньшая половина чисел — max-куча: на вершине самое большое из маленьких
  private low = new Heap<number>((a, b) => a > b);
  // Большая половина чисел — min-куча: на вершине самое маленькое из больших
  private high = new Heap<number>((a, b) => a < b);

  // Инвариант: low.size() === high.size() или low.size() === high.size() + 1,
  // и каждый элемент low не больше любого элемента high

  addNum(num: number): void {
    // Сначала кладём в нижнюю половину,
    // а её максимум перекидываем наверх — так порядок половин сохраняется
    this.low.push(num);
    this.high.push(this.low.pop()!);

    // Возвращаем баланс размеров: нижняя половина не меньше верхней
    if (this.high.size() > this.low.size()) {
      this.low.push(this.high.pop()!);
    }
  }

  findMedian(): number {
    // Нечётное количество — медиана на вершине нижней половины
    if (this.low.size() > this.high.size()) return this.low.peek()!;
    // Чётное — среднее двух «средних» вершин
    return (this.low.peek()! + this.high.peek()!) / 2;
  }
}

// Время: addNum — O(log n), findMedian — O(1)
// Память: O(n)
